function getQuizFor(part=quizPart,mode=quizMode){
  const meta=quizParts[part]||quizParts["l1-all"];
  let base;
  if(meta.pool==="next")base=mode==="mastery"?masteryQuizNext:reviewQuizNext;
  else if(meta.pool==="l2gdp")base=mode==="mastery"?masteryQuizL2GDP:reviewQuizL2GDP;
  else if(meta.pool==="l2ui")base=mode==="mastery"?masteryQuizL2UI:reviewQuizL2UI;
  else if(meta.pool==="l3")base=mode==="mastery"?masteryQuizL3:reviewQuizL3;
  else if(meta.pool==="l4")base=mode==="mastery"?masteryQuizL4:reviewQuizL4;
  else base=mode==="mastery"?masteryQuiz:reviewQuiz;
  return meta.topics?base.filter(q=>meta.topics.includes(q.topic)):base;
}
