function shuffledCopy(arr){
  const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;
}
function makeOptionOrders(qs){
  const targets=[];
  for(let i=0;i<qs.length;i++)targets.push(i%4);
  const balanced=shuffledCopy(targets);
  return qs.map((q,i)=>{
    const correct=q.ans,rest=shuffledCopy([0,1,2,3].filter(x=>x!==correct)),order=[];
    let r=0;for(let p=0;p<4;p++)order[p]=p===balanced[i]?correct:rest[r++];
    return order;
  });
}
function freshQuizSession(mode=quizMode,part=quizPart){
  const q=getQuizFor(part,mode);
  return{mode,part,answers:Array(q.length).fill(null),confidence:Array(q.length).fill("confident"),optionOrders:makeOptionOrders(q),current:0,submitted:false}
}
function loadQuizDraft(mode=quizMode,part=quizPart){
  const q=getQuizFor(part,mode);
  try{
    let raw=localStorage.getItem(draftKey(mode,part));
    if(!raw&&part==="l1-all") raw=localStorage.getItem(oldDraftKey(mode));
    const d=JSON.parse(raw||"null");
    if(d&&Array.isArray(d.answers)&&d.answers.length===q.length&&!d.submitted){
      d.mode=mode;d.part=part;
      d.confidence=Array.isArray(d.confidence)&&d.confidence.length===q.length?d.confidence:Array(q.length).fill("confident");
      d.optionOrders=Array.isArray(d.optionOrders)&&d.optionOrders.length===q.length?d.optionOrders:makeOptionOrders(q);
      return d;
    }
  }catch(e){}
  return freshQuizSession(mode,part);
}
