function updateActiveUserRecord(mutator){
  const users=getUsers(),idx=users.findIndex(function(u){return u.id===activeUser?.id});if(idx<0)return false;
  mutator(users[idx]);users[idx]=normalizeUserRecord(users[idx]);setUsers(users);activeUser=users[idx];return true;
}
function grantSubjectAccess(subjectId){
  if(!activeUser)return false;
  const ok=updateActiveUserRecord(function(u){u.subjectAccess=u.subjectAccess||{};u.subjectAccess[subjectId]={unlockedAt:new Date().toISOString(),version:APP_VERSION}});
  if(ok)appendDevActivity("Subject unlocked",subjectId.toUpperCase()+" permanently unlocked for this local account.",activeUser);
  return ok;
}
function revokeSubjectAccess(userId,subjectId){
  const users=getUsers(),idx=users.findIndex(function(u){return u.id===userId});if(idx<0)return;
  if(users[idx].subjectAccess)delete users[idx].subjectAccess[subjectId];setUsers(users);
  if(activeUser&&activeUser.id===userId){activeUser=normalizeUserRecord(users[idx]);clearSubjectSession();activeSubject=null;const appShell=document.getElementById("appShell");if(appShell)appShell.style.display="none"}
  appendDevActivity("Subject access revoked",subjectId.toUpperCase()+" access revoked for "+users[idx].username,users[idx]);
  renderDevSubjectAccess();renderSubjectHub();
}
