  if(dvc&&!dvc.dataset.bound){dvc.dataset.bound="1";dvc.onclick=closeDevPanel}
  if(dvx&&!dvx.dataset.bound){dvx.dataset.bound="1";dvx.onclick=closeDevPanel}
  if(dvl&&!dvl.dataset.bound){dvl.dataset.bound="1";dvl.onclick=lockDevPanel}
  if(dve&&!dve.dataset.bound){dve.dataset.bound="1";dve.onclick=exportDevSnapshot}
