function logout(){saveQuizDraft();persist();appendDevActivity("Signed out","Local profile signed out.",activeUser);clearSubjectSession();sessionStorage.removeItem(ACTIVE_KEY);localStorage.removeItem(ACTIVE_KEY);location.reload()}
function restoreSession(){
  let id=null;
  try{
    const saved=JSON.parse(localStorage.getItem(ACTIVE_KEY)||"null");
    if(saved&&saved.id&&saved.expiresAt>Date.now()) id=saved.id;
    else if(saved) localStorage.removeItem(ACTIVE_KEY);
  }catch(e){}
  if(!id) id=sessionStorage.getItem(ACTIVE_KEY);
  if(!id)return;
  const user=getUsers().find(x=>x.id===id);
  if(user)startUser(user,false);
}
function migrateLegacy(){
  try{
    const old=JSON.parse(localStorage.getItem("ec214-study-state")||"null");
    if(old){state=normalizeState(old);persist()}
    const d=JSON.parse(localStorage.getItem("ec214-quiz-draft")||"null");
    if(d&&Array.isArray(d.answers)&&d.answers.length===masteryQuiz.length){
      d.mode="mastery";d.confidence=Array(masteryQuiz.length).fill("confident");
      localStorage.setItem(draftKey("mastery"),JSON.stringify(d));
    }
    document.getElementById("legacyBox").style.display="none";
    renderTracker();renderHistory();alert("Old progress imported into this profile.");
  }catch(e){alert("Could not import the old local data.")}
}


