const THEME_ACCENT_NAMES={
  classic:{navy:"Classic Navy",violet:"Classic Violet",forest:"Classic Forest",rose:"Classic Rose",amber:"Classic Amber"},
  neo:{navy:"Electric Azure",violet:"Ultraviolet",forest:"Neo Emerald",rose:"Coral Pulse",amber:"Digital Gold"},
  midnight:{navy:"Sapphire",violet:"Amethyst",forest:"Jade",rose:"Ruby",amber:"Bronze"}
};
function applyThemeAccentLabels(uiTheme){
  const names=THEME_ACCENT_NAMES[uiTheme]||THEME_ACCENT_NAMES.classic;
  document.querySelectorAll(".swatch").forEach(b=>{
    const label=names[b.dataset.color]||b.dataset.color;
    b.title=label;b.setAttribute("aria-label",label);
  });
  const hint=document.getElementById("themeColorHint");
  if(hint){
    const family=uiTheme==="midnight"?"Midnight premium":uiTheme==="neo"?"Neo electric":"Classic";
    hint.textContent=family+" palette • changes navigation, active cards, quiz selection, progress accents, links, and controls.";
  }
}
function applyPreferences(){
  if(!state)return;
  const p=state.preferences||defaultPreferences();
  document.body.dataset.accent=p.accent||"navy";
  const dark=p.appearance==="dark"||(p.appearance==="system"&&window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches);
  document.body.classList.toggle("dark",dark);
  const uiTheme=p.uiTheme||"classic";
  document.body.classList.toggle("neo-ui",uiTheme==="neo");
  document.body.classList.toggle("midnight-ui",uiTheme==="midnight");
  document.body.dataset.uiTheme=uiTheme;
  applyThemeAccentLabels(uiTheme);
  document.body.classList.toggle("large-text",p.textSize==="large");
  document.body.classList.toggle("flat-cards",p.cardStyle==="flat");
  if(!fontPreviewActive)applyFontKey(p.font||"inter");
  document.querySelectorAll(".swatch").forEach(b=>b.classList.toggle("active",b.dataset.color===p.accent));
  document.querySelectorAll("[data-ui-theme]").forEach(b=>b.classList.toggle("active",b.dataset.uiTheme===(p.uiTheme||"classic")));
  const a=document.getElementById("appearanceSelect"),t=document.getElementById("textSizeSelect"),c=document.getElementById("cardStyleSelect"),f=document.getElementById("fontSelect");
  if(a)a.value=p.appearance;if(t)t.value=p.textSize;if(c)c.value=p.cardStyle;if(f&&!fontPreviewActive)f.value=p.font||"inter";
}
