function simpleTextHash(str){
  let h=2166136261;
  for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}
  return (h>>>0).toString(36);
}
function questionNoteKey(q,part=quizPart){return part+"::"+simpleTextHash(q.q)}
function getSectionNote(part=quizPart){return state.quizNotes?.sections?.[part]||""}
function getQuestionNote(q,part=quizPart){return state.quizNotes?.questions?.[questionNoteKey(q,part)]||""}
function saveSectionNote(value,part=quizPart){state.quizNotes.sections[part]=value;persist()}
function saveQuestionNote(q,value,part=quizPart){state.quizNotes.questions[questionNoteKey(q,part)]=value;persist()}
function confidenceWeight(c){return c==="guessed"?.4:c==="unsure"?.7:1}
